<?php
namespace App\Http\Controllers;
use App\Models\{EggProduct,InventoryTransaction,ProductionRecord}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class ProductionController { public function index(){return view('admin.production.index',['products'=>EggProduct::where('status','active')->orderBy('product_name')->get(),'records'=>ProductionRecord::with('product','recorder')->latest('production_date')->paginate(12)]);} public function store(Request $r){$d=$r->validate(['product_id'=>'required|exists:egg_products,id','production_date'=>'required|date','quantity_produced'=>'required|integer|min:0','saleable_quantity'=>'required|integer|min:0','damaged_quantity'=>'required|integer|min:0','rejected_quantity'=>'required|integer|min:0','notes'=>'nullable|string']);if($d['saleable_quantity']+$d['damaged_quantity']+$d['rejected_quantity']>$d['quantity_produced'])return back()->withErrors(['saleable_quantity'=>'Classified quantities cannot exceed total production.'])->withInput();DB::transaction(function()use($d,$r){$rec=ProductionRecord::create($d+['recorded_by'=>$r->user()->id]);if($rec->saleable_quantity>0)InventoryTransaction::create(['product_id'=>$rec->product_id,'production_id'=>$rec->id,'transaction_type'=>'addition','quantity'=>$rec->saleable_quantity,'reason'=>'Production','transaction_date'=>$rec->production_date,'recorded_by'=>$r->user()->id,'remarks'=>'Automatic addition from production entry.']);});return back()->with('success','Production record saved.');} }
